import { AuthError } from "next-auth";
import { signIn } from "@/lib/auth";

export type FormState = { error?: string } | undefined;

export async function authenticateWithCredentials(
  _prevState: FormState,
  formData: FormData
): Promise<FormState> {
  try {
    await signIn("credentials", {
      email: formData.get("email"),
      password: formData.get("password"),
      redirectTo: (formData.get("callbackUrl") as string) || "/dashboard",
    });
  } catch (error) {
    if (error instanceof AuthError) {
      switch (error.type) {
        case "CredentialsSignin":
          return { error: "Invalid email or password." };
        default:
          return { error: "Something went wrong signing you in." };
      }
    }
    // Next.js uses a thrown redirect internally on success — let it propagate.
    throw error;
  }
}

export async function authenticateWithGoogle(formData: FormData) {
  await signIn("google", {
    redirectTo: (formData.get("callbackUrl") as string) || "/dashboard",
  });
}

